// SPEC-M3-link-batch-v24 4.2: the e2-editor-v24 worker.  Derived from the
// frozen v23 worker (sdk/v23-feature-worker.js, 3fd3e1e6...), which stays
// byte-identical because generation 76 and the v23 profile bind it.  The
// differences are a closed list (criterion W1): (1) insertText routes on the
// SDK's `route`; (2) `insertTypedText` joins the declared document exports;
// (3) init refuses a binary that lacks a declared export; (4)
// featureExtendPermitted names this profile; (5) this comment; (6) the
// `inserted` reply names `completion` and `resultPayload` (the projection is
// a whitelist, so without it the typed route's proof never reaches the page).

//
// SPEC-M3-link-batch-v24 4.2: `insertTypedText` is the third.  It is not a
// wire operation of its own -- typed text arrives as insertText with
// `route: "uno-insert-text"` (exportOperation below) -- so a leafless manifest
// answers UNSUPPORTED_OPERATION here instead of reaching for a symbol its
// binary may not have.  `symbol` is what init's presence check looks for.

const INSERT_ROUTES = new Set(["uno-insert-text", "paste"]);

function exportOperation(request) {
  return request.operation === "insertText"
      && request.payload?.route === "uno-insert-text"
    ? "insertTypedText" : request.operation;
}

// SPEC-M3-link-batch-v24 4.2 (6): the typed route's reply carries its
// completion and the raw UNO_COMMAND_RESULT payload (T2 reads both).  Named
// only when the engine sent them, so a paste reply keeps its v23 shape.

complete(requestId, {
  method: event.method,
  revision: event.revision,
  ...(event.completion === undefined ? {} : {
    completion: event.completion,
    resultPayload: event.resultPayload,
  }),
});

// SPEC-M3-link-batch-v24 4.2 (fable ruling 2): what an ABI bump would
// have caught at init.  A declaration is a claim about the binary; a
// stale wasm beside a fresh manifest must be refused here, not surface as
// WORKER_EXCEPTION at the first typed character.
for (const spec of DOCUMENT_EXPORT_OPERATIONS.values()) {
  if (contract?.[spec.field] === spec.declaration
      && typeof moduleInstance?.["_" + spec.symbol] !== "function") {
    fail(request.requestId, "DECLARED_EXPORT_MISSING",
         `profile ${activeManifest?.profile || "unknown"} declares `
         + `${spec.field}: "${spec.declaration}" but this binary has no `
         + `${spec.symbol}`);
    return;
  }
}

// SPEC-M3-link-batch-v24 4.2: the SDK decides the route and says so;
// this layer only refuses a route it does not know.  Typed text was gated
// above on the `typedInsert` declaration.

if (payload.route !== undefined && !INSERT_ROUTES.has(payload.route)) {
  postResponse(request.requestId, false, {
    code: "INVALID_ARGUMENT",
    message: `unknown insertText route ${JSON.stringify(payload.route)}`,
    dispatched: false,
  });
  break;
}
